// gumbel_sampler.h — chain-bound Gumbel-max sampler contract (research, v1).
//
// C++ mirror of gumbel_sampler.py for the llama.cpp miner (pow_utils.cpp
// PowSamplingCoordinator) and the native ProofProcessor. The Python module is
// normative; tests/vectors/gumbel_vectors.json (generated by
// tests/gen_gumbel_vectors.py) pins both implementations bit-for-bit
// (tests/test_gumbel_cpp.cpp).
//
// Contract summary (full text in gumbel_sampler.py):
//   D        = SHA-256 of the step preimage with the mode suffix appended
//              (sampling_u stays digest_to_u(D), as in production)
//   seed_d   = (LE256(D) + d) mod 2^256, d in {0 (KEEP), 1 (SWITCH)}
//   m_i      = TAG(8) | seed_d(32) | u32le(token_id)          (44 bytes)
//   u_i      = ((LE64(SHA256(m_i)[0:8]) >> 12) + 0.5) / 2^52   in (0,1), exact
//   g_i      = -DLOG(-DLOG(u_i)),  score_i = double(a_i) + g_i   BIT-EXACT:
//              DLOG is the contract's deterministic log (only IEEE basic ops in a
//              fixed order, table of 129 shipped bit patterns, NO libm, NO FMA —
//              this TU must be compiled with contraction off; dlog_selftest()
//              fails loudly otherwise). RACE_ATOL is 0.
//   winner   = argmax score over the support; ties -> smallest token id
//   switch   = inferred ex post: chosen wins draw 0 -> KEEP, else wins draw 1
//              -> SWITCH, else invalid. Nothing is declared in the proof.
//   carrier  = extra_flags {"gumbel":{"v":1,"head":"h0"}} (bound mode only)
//
// Switch abstraction: SwitchPolicy::decide(const SwitchFeatures&) — any
// function of the miner-visible logit vector / race state, from the
// interpretable race-margin rule to a small MLP classifier (MlpSwitchPolicy).
#ifndef GUMBEL_SAMPLER_H
#define GUMBEL_SAMPLER_H

#include <array>
#include <cmath>
#include <cstddef>
#include <cstdint>
#include <functional>
#include <memory>
#include <optional>
#include <string>
#include <vector>

namespace gumbel {

// ------------------------------------------------------------------------- //
// Constants — mirror gumbel_sampler.py exactly
// ------------------------------------------------------------------------- //
constexpr int CONTRACT_VERSION = 1;
constexpr char TAG[] = "TCGUMBL1";            // 8 bytes, no NUL
constexpr std::size_t TAG_LEN = 8;
constexpr char MODE_TAG[] = "TCGMODE1";       // 8 bytes, no NUL
constexpr std::size_t MODE_TAG_LEN = 8;
constexpr std::size_t SEED_BYTES = 32;
constexpr std::size_t EXPANSION_MSG_BYTES = TAG_LEN + SEED_BYTES + 4;   // 44
constexpr std::size_t WINDOW_BITS = 256;
constexpr double TWO_POW_52 = 4503599627370496.0;
constexpr double DEFAULT_RACE_ATOL = 0.0;      // the race is bit-exact
constexpr double DLOG_LN2 = 0.6931471805599453;
constexpr double DLOG_NEAR_LO = 0.99609375;
constexpr double DLOG_NEAR_HI = 1.0078125;
extern const int64_t DLOG_TABLE_BITS[129];        // correctly rounded log(1 + k/128), as bits
constexpr int SUPPORT_CAP = 50;
constexpr const char* DEFAULT_HEAD = "h0";

bool is_valid_head(const std::string& head);          // h0 | h1 | h2

// MODE_TAG | u8(version) | head  (11 bytes for the v1 heads). Appended LAST to
// every step preimage and to the window's final hash under the Gumbel sampler.
std::vector<uint8_t> mode_suffix(const std::string& head = DEFAULT_HEAD,
                                 int version = CONTRACT_VERSION);

// Research contract v2 (TWO end states; selected only by POW_GUMBEL_MODE_VERSION=2
// on the Python side). 'TCGMODE2' | u8(2) | head (2) | u8(arm: 1=ONE, 2=TWO) |
// SHA256("xhg.two.policy|" + canonical policy JSON)[:8]  = 20 bytes.
// The canonical policy JSON is produced by gumbel_sampler.py and carried
// verbatim; C++ never re-serialises floats.
constexpr int CONTRACT_VERSION_V2 = 2;
constexpr char MODE_TAG_V2[] = "TCGMODE2";    // 8 bytes, no NUL
constexpr const char* POLICY_DIGEST_DOMAIN = "xhg.two.policy|";
int arm_code(const std::string& arm);                  // "ONE" -> 1, "TWO" -> 2, else throws
std::vector<uint8_t> mode_suffix_v2(const std::string& head, const std::string& arm,
                                    const std::string& canonical_policy_json);

// ------------------------------------------------------------------------- //
// Reference arithmetic
// ------------------------------------------------------------------------- //
std::array<uint8_t, 32> seed_from_digest(const uint8_t* digest32, uint64_t draw);
std::vector<uint8_t> expansion_message(const std::array<uint8_t, 32>& seed, uint32_t token_id);
std::array<uint8_t, 32> sha256_bytes(const uint8_t* data, std::size_t len);   // OpenSSL EVP
double uniform_from_x64(uint64_t x);
double token_uniform(const std::array<uint8_t, 32>& seed, uint32_t token_id);
// Deterministic natural log of a positive normal double (the contract's DLOG).
double dlog(double x);
// Throws std::runtime_error if this build's dlog deviates from the reference bits
// (FP contraction enabled, non-IEEE double arithmetic, ...). Call once at startup.
void dlog_selftest();
double gumbel_from_uniform(double u);           // -dlog(-dlog(u))
double token_gumbel(const std::array<uint8_t, 32>& seed, uint32_t token_id);

struct RaceResult {
    int winner_pos = -1;                  // index into ids/weights, -1 = empty support
    int64_t winner_id = -1;
    double best = -INFINITY;
    double second = -INFINITY;            // best among the other support tokens
    std::vector<double> scores;           // per position, -inf outside support
    double margin() const { return best - second; }
};

// Race over the support: weights are float32 log-weights AFTER the sampling
// transforms (-inf outside the support); ids must be unique.
RaceResult race(const std::vector<int64_t>& ids, const std::vector<float>& weights,
                const std::array<uint8_t, 32>& seed);

// softmax over the finite weights (double), 0 outside the support.
std::vector<double> support_probs(const std::vector<float>& weights);

std::string bytes_hex(const uint8_t* data, std::size_t len);

// ------------------------------------------------------------------------- //
// Declaration carrier
// ------------------------------------------------------------------------- //
struct Decl {
    int version = CONTRACT_VERSION;
    std::string head = DEFAULT_HEAD;
    std::string arm;              // v2 only: "ONE" | "TWO"
    std::string policy_json;      // v2 only: canonical policy object (verbatim)
    std::vector<uint8_t> mode_suffix() const {
        return version == CONTRACT_VERSION_V2 ? gumbel::mode_suffix_v2(head, arm, policy_json)
                                              : gumbel::mode_suffix(head, version);
    }
};

// Producer-side merge of {"gumbel":{"v":1,"head":..}} as a top-level member of
// an existing extra_flags / model_config_diff JSON object (idempotent: an
// existing "gumbel" member is replaced; other members preserved; a non-object
// input is kept under "_diff", like pow_v3::merge_extra_flags_v3).
std::string merge_extra_flags_gumbel(const std::string& extra_flags, const Decl& decl);

// Strict extraction (mirror of gumbel_sampler.extract_gumbel_decl): nullopt
// unless the exact shape is present. Never throws.
std::optional<Decl> extract_gumbel_decl(const std::string& extra_flags);

// ------------------------------------------------------------------------- //
// Switch-policy abstraction
// ------------------------------------------------------------------------- //
struct SwitchFeatures {
    const std::vector<int64_t>* ids = nullptr;       // support token ids
    const std::vector<float>* weights = nullptr;     // log-weights (-inf outside support)
    const std::vector<double>* probs = nullptr;      // softmax over the support
    const RaceResult* race0 = nullptr;               // draw-0 race
    const RaceResult* race1 = nullptr;               // draw-1 race (only if needs_draw1)
    int step = 0;                                    // window position 0..255
    int retries_used = 0;                            // switches spent in this window
    int remaining() const { return int(WINDOW_BITS) - 1 - step; }
};

// (8,) feature vector for learned policies — mirrors
// gumbel_sampler.default_feature_vector: [margin0, margin1, p_winner0,
// entropy, log(support), step/256, remaining/256, retries_used].
std::vector<float> default_feature_vector(const SwitchFeatures& f);

class SwitchPolicy {
public:
    virtual ~SwitchPolicy() = default;
    virtual bool needs_draw1() const { return false; }
    virtual const char* name() const = 0;
    // true = SWITCH to draw 1, false = KEEP draw 0
    virtual bool decide(const SwitchFeatures& f) const = 0;
};

class NeverSwitchPolicy : public SwitchPolicy {
public:
    const char* name() const override { return "never"; }
    bool decide(const SwitchFeatures&) const override { return false; }
};

class AlwaysSwitchPolicy : public SwitchPolicy {      // diagnostic only
public:
    const char* name() const override { return "always"; }
    bool decide(const SwitchFeatures&) const override { return true; }
};

// Interpretable "race distance" rule: switch when best-second < threshold.
class RaceMarginPolicy : public SwitchPolicy {
public:
    explicit RaceMarginPolicy(double threshold) : threshold_(threshold) {}
    const char* name() const override { return "margin"; }
    bool decide(const SwitchFeatures& f) const override {
        return f.race0 && f.race0->margin() < threshold_;
    }
    double threshold() const { return threshold_; }
private:
    double threshold_;
};

// P2 'margin + stabilisation' (TWO frozen family margin_stab): switch when the
// draw-0 margin < theta AND the draw-1 margin > ratio * max(margin0, 1e-12).
class RaceMarginStabPolicy : public SwitchPolicy {
public:
    RaceMarginStabPolicy(double theta, double ratio) : theta_(theta), ratio_(ratio) {}
    bool needs_draw1() const override { return true; }
    const char* name() const override { return "margin_stab"; }
    bool decide(const SwitchFeatures& f) const override {
        if (!f.race0 || !f.race1) return false;
        const double m0 = f.race0->margin();
        return m0 < theta_ && f.race1->margin() > ratio_ * std::max(m0, 1e-12);
    }
    double theta() const { return theta_; }
    double ratio() const { return ratio_; }
private:
    double theta_, ratio_;
};

// Any function of the features.
class CallableSwitchPolicy : public SwitchPolicy {
public:
    CallableSwitchPolicy(std::function<bool(const SwitchFeatures&)> fn,
                         bool needs_draw1 = false, std::string name = "callable")
        : fn_(std::move(fn)), needs_draw1_(needs_draw1), name_(std::move(name)) {}
    bool needs_draw1() const override { return needs_draw1_; }
    const char* name() const override { return name_.c_str(); }
    bool decide(const SwitchFeatures& f) const override { return fn_(f); }
private:
    std::function<bool(const SwitchFeatures&)> fn_;
    bool needs_draw1_;
    std::string name_;
};

// Small dense classifier (ReLU MLP; output logit > threshold means SWITCH)
// over default_feature_vector. Weight file format (text):
//   mlp <n_layers>
//   <in> <out>            followed by out*in weights (row-major) then out biases
//   ... repeated per layer; last layer has out == 1
class MlpSwitchPolicy : public SwitchPolicy {
public:
    struct Layer { int in = 0, out = 0; std::vector<float> w, b; };
    MlpSwitchPolicy(std::vector<Layer> layers, bool needs_draw1 = false, float threshold = 0.0f);
    static MlpSwitchPolicy load(const std::string& path, bool needs_draw1 = false, float threshold = 0.0f);
    bool needs_draw1() const override { return needs_draw1_; }
    const char* name() const override { return "mlp"; }
    bool decide(const SwitchFeatures& f) const override;
    float forward(const std::vector<float>& x) const;
private:
    std::vector<Layer> layers_;
    bool needs_draw1_;
    float threshold_;
};

// POW_GUMBEL_SWITCH_POLICY: never | always | margin:<thr> |
// margin_stab:theta=<t>,ratio=<r> | mlp:<path>
std::unique_ptr<SwitchPolicy> policy_from_spec(const std::string& spec);
std::unique_ptr<SwitchPolicy> policy_from_env();
int max_retries_from_env();                            // POW_GUMBEL_MAX_RETRIES (default 256)
double race_atol_from_env();                           // POW_GUMBEL_RACE_ATOL (default 1e-9)

// ------------------------------------------------------------------------- //
// One full sampler step (miner) and the verifier-side check
// ------------------------------------------------------------------------- //
struct SampleResult {
    int64_t token_id = -1;
    int draw = 0;                           // 0 KEEP / 1 SWITCH (miner-local; not in the proof).
                                            // 1 only for an OBSERVABLE switch: a fire whose
                                            // two draws pick the same token stays 0 (KEEP).
    bool switch_requested = false;          // what the policy asked before the budget
    float u_value = 0.0f;                   // digest_to_u(D) for the proof's sampling_u
    float prob = 0.0f;                      // softmax prob of the chosen token
    double margin0 = 0.0;                   // draw-0 race margin
    double margin_used = 0.0;               // margin of the producing draw
};

// ids/weights: the reconstructed support (-inf outside); digest32: the step
// digest D; policy may be null (== NeverSwitch).
SampleResult sample(const std::vector<int64_t>& ids, const std::vector<float>& weights,
                    const uint8_t* digest32, const SwitchPolicy* policy,
                    int step, int retries_used, int max_retries);

struct VerifyResult {
    bool ok = false;                         // chosen token wins draw 0 or draw 1
    int draw = -1;                           // inferred: 0 KEEP, 1 SWITCH, -1 invalid
    int64_t winner0_id = -1;
    int chosen_pos = -1;
    double chosen_prob = 0.0;                // adapter 'upper' (lower is 0)
    double margin0 = 0.0;
    double slack = 0.0;                      // score_chosen - score_best on the winning draw
    float u_value = 0.0f;                    // expected sampling_u (== digest_to_u(D))
};

VerifyResult verify_race(const std::vector<int64_t>& ids, const std::vector<float>& weights,
                         const uint8_t* digest32, int64_t chosen,
                         double atol = DEFAULT_RACE_ATOL);

// float32 u of the first four little-endian bytes (== pow_utils digest_to_u).
float digest_to_u_f32(const uint8_t* bytes4);

}  // namespace gumbel

#endif  // GUMBEL_SAMPLER_H
